  int ret = reset_builder();
  if (ret != 0) return ret;
  build_stage_ = BuildStage::kCollecting;
  ret = Index::merge(indexes, filter, options);
  if (ret != 0) return ret;
  build_stage_ = BuildStage::kBuilt;
  is_trained_ = false;
  return dump_and_open();
}

